--region handler
function ActivityCrisisContractTaskCell:OnBtnClickHandler()
    if self._isDraw then
        GameUtils.Toast(localize("已领取"))
        return
    end

    if self._isCanDraw and not self._isDraw then
        -- 领取
        if not isNull(self.callBack) then
            self.callBack(self._taskInfo)
        end
    else
        -- 前往
        if checkNumber(self._taskInfo.openType) > 0 then
            --[[local row = GoodsConfMgr:GetInstance():GetJumpModuleRow(self._taskInfo.openType)
            local t = checkTable(CfUtils.Split(self._taskInfo.openParameter))
            GoodsConfMgr:GetInstance():ExecuteJump(row, nil, nil, nil, t)]]
        end
    end
end
--endregion handler

--region public

---@param taskInfo MidFestivalTaskStruct
function ActivityCrisisContractTaskCell:Refresh(taskInfo)
    self._taskInfo = taskInfo
    if isNull(self._taskInfo) then
        return
    end
    self._isCanDraw = checkBool(taskInfo.status == 1)
    self._isDraw = checkBool(taskInfo.status == 2)
    self._isUnderWay = checkBool(taskInfo.status == 99)
    self:RefreshUI()
end
--endregion public

--region private
function ActivityCrisisContractTaskCell:RefreshUI()
    CfUtils.SetUISwitchImage(self.ImgDecorate, self._isCanDraw and 2 or 1)
    ---@type ActivityCrisisUtils
    local ActivityCrisisUtils = import('Game.Activity.CrisisContract.ActivityCrisisUtils')
    local taskVo = ActivityCrisisUtils.GetCrisisEventTaskVo(self._taskInfo.id)

    CfUtils.FillText(self.NameTxt, taskVo.desc)
    local num = 0
    if self._isDraw then
        num = 1
    else
        num = self._isCanDraw and 1 or 0
    end
    self.Slider.value = num

    CfUtils.FillText(self.TitleText, localize("<size=30><color=#545454>_num1_</color></size>/_num2_", {_num1_ = num, _num2_ = 1}))

    CfUtils.SetActive(self.HasReceived, self._isDraw)
    CfUtils.SetActive(self.FontStyleButton, not self._isDraw and not self._isUnderWay)
    local fontStyleBtn = KTool.GetComponent(self.FontStyleButton.gameObject ,typeof(CS.Game.Native.Common.FontStyleButton) )
    CfUtils.SetActive(self.TextUnderway, self._isUnderWay)
    if self._isCanDraw and not self._isDraw then
        fontStyleBtn:ResetFontStyle("B12" , localize("领取"))
    else
        if self._isDraw then
            CfUtils.SetActive(self.TextUnderway, false)
        else
            --TODO 跳转现在不方便做  后面再优化 先显示成进行中
            CfUtils.SetActive(self.TextUnderway, true)
        end
        CfUtils.SetActive(self.FontStyleButton,false)
        --fontStyleBtn:ResetFontStyle("B13" , localize("前往"))
    end

    local isHaveLimitRewards = checkNumber(self._taskInfo.limitCountdown) > 0 and (checkNumber(self._taskInfo.limitCountdown) - os.time() > 0)
    local rewards = isHaveLimitRewards and taskVo.allRewards or taskVo.rewards

    for i, v in pairs(rewards) do
        if v.isLimit then
            v.duration = isHaveLimitRewards and checkNumber(self._taskInfo.limitCountdown) - os.time()  or 0
            --v.duration = isHaveLimitRewards and 10000000  or 0
        end
    end


    ---@type CommonGoodsList
    local scr = CfUtils.GetLuaScr(self.CommonGoodsList, "Game.Behaviours.CommonGoodsList")
    scr:FreshBaseUI(rewards)
    scr:SetCountDownShow(CfUtils.GetTimeHMS10)
end
--endregion private

--region get / set
--endregion get / set

return ActivityCrisisContractTaskCell
